def metric(data: pd.DataFrame) -> float:
    matches = 0
    total = 0
    for a, b, r in zip(data['option_a_ratings'], data['option_b_ratings'], data['response']):
        choice = -1
        for j in range(len(a)):
            if a[j] > b[j]:
                choice = 0
                break
            elif b[j] > a[j]:
                choice = 1
                break
        if choice == r:
            matches += 1
        total += 1
    return float(matches) / total if total > 0 else 0.0

