def metric(data: pd.DataFrame) -> float:
    ttb_choices = 0
    conflict_trials = 0

    order = [1, 0, 3, 2, 4]

    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']

        ttb_pred = None
        for idx in order:
            if a[idx] > b[idx]:
                ttb_pred = 0
                break
            elif b[idx] > a[idx]:
                ttb_pred = 1
                break

        sum_a = sum(a)
        sum_b = sum(b)
        tally_pred = None
        if sum_a > sum_b:
            tally_pred = 0
        elif sum_b > sum_a:
            tally_pred = 1

        if ttb_pred is not None and tally_pred is not None and ttb_pred != tally_pred:
            conflict_trials += 1
            if row['response'] == ttb_pred:
                ttb_choices += 1

    if conflict_trials == 0:
        return 0.5
    return ttb_choices / conflict_trials

